const Bitmap* find_system(std::string_view id) {
  for (int i = 0; i < kSystemCount; ++i) {
    if (id == kSystem[i].id) {
      return &kSystem[i];
    }
  }
  return nullptr;
}

const Bitmap* find_icon(std::string_view id) {
  for (int i = 0; i < kIconCount; ++i) {
    if (kIcons[i].id != nullptr && id == kIcons[i].id) {
      return &kIcons[i];
    }
  }
  return nullptr;
}

